package com.interviewiq.ai; import org.springframework.stereotype.Service; @Service public class AdaptiveService { public String next(String cur,double s){ if(s>=85) return cur.equals("Easy")?"Medium":"Hard"; if(s>=70) return cur; return cur.equals("Hard")?"Medium":"Easy"; } public String reason(double s){ if(s>=85) return "Difficulty increased because your previous answer demonstrated strong understanding."; if(s>=70) return "Difficulty maintained to consolidate your current level."; return "Reinforcement question selected to strengthen fundamentals."; } }
